// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(uint256 seed) public {
        // The stored paused flag starts false; paused() must report the stored state.
        // The fuzzer's seed does not change the invariant: for any input, paused()
        // must equal the underlying storage value (false here), which the mutant violates.
        vm.assume(seed < type(uint256).max); // keep domain wide, no effect on invariant

        // Read c's public surface: paused() view return.
        bool reported = c.paused();

        // General rule: paused() reports the actual (initially false) pause state.
        assertTrue(reported == false);
    }
}
